/* @lc app=leetcode id=3070 lang=kotlin */ class Solution { fun countSubmatrices(grid: Array<IntArray>, k: Int): Int = Array(grid.size) { IntArray(grid[0].size) }.also { p -> grid.indices.forEach { i -> grid[0].indices.forEach { j -> p[i][j] = grid[i][j] + (if (i > 0) p[i - 1][j] else 0) + (if (j > 0) p[i][j - 1] else 0) - (if (i > 0 && j > 0) p[i - 1][j - 1] else 0) } } }.sumOf { r -> r.count { it <= k } } }